package com.northstarbank.console.data;import com.northstarbank.console.security.AuthorizationService;import com.northstarbank.console.service.AuditService;import java.time.LocalDate;import java.util.*;import org.springframework.stereotype.Service;
@Service public class TransactionSearchService{private static final Map<String,String>SORTS=Map.of("date","booking_date","amount","amount","description","description");private final TransactionSortMapper sorted;private final TransactionTextMapper text;private final AuthorizationService auth;private final AuditService audit;public TransactionSearchService(TransactionSortMapper s,TransactionTextMapper t,AuthorizationService a,AuditService l){sorted=s;text=t;auth=a;audit=l;}public List<TransactionRow> find(String customer,String branch,String term,String sort,String direction,LocalDate from,LocalDate to){var d=auth.require("TRANSACTION_READ",branch,false);List<TransactionRow> rows;if(term!=null&&!term.isBlank())rows=text.search(customer,term.substring(0,Math.min(80,term.length())));else{String column=SORTS.getOrDefault(sort,"booking_date");String dir="asc".equalsIgnoreCase(direction)?"ASC":"DESC";rows=sorted.sorted(customer,from,to,column,dir);}audit.record("TRANSACTION_READ","transaction",rows.size(),customer,d.authorizationBasis(),null,"rows="+rows.size());return rows;}}
